# same graph, print relevant controller direct edges and closure chains
import re,pathlib
files=list(pathlib.Path('.').glob('*/src/main/java/**/*.java'))
def clean(s):
 s=re.sub(r'/\\*.*?\\*/',' ',s,flags=re.S); s=re.sub(r'//["'^'"\\n]*',' ',s); s=re.sub(r'\"(?:\\\\.|["'^"'"\\\\])*\"','\"\"',s); s=re.sub(r\"'(?:\\\\.|["'^'"'\\\\])*'\",\"''\",s); return s
infos=[]; names=set()
for p in files:
 s=clean(p.read_text(errors='ignore')); ds=re.findall(r'\\b(?:class|interface|enum|record)\\s+(\\w+)',s); own=ds[0] if ds else p.stem; infos.append((p,s,own)); names.update(ds)
edges={};
for p,s,own in infos:
 body=re.sub(r'\\b(?:import|package)\\s+["'^;]+;'"',' ',s); present=set(re.findall(r'\\b[A-Z]\\w*\\b',body))&names; e=set()
 for n in present-{own}:
  q=re.escape(n)
  if re.search(r'\\b'+q+r'\\b\\s+\\w+\\s*(?:[=;,)\\]])',body) or re.search(r'\\bnew\\s+'+q+r'\\b',body) or re.search(r'\\b(?:extends|implements)\\b["'^'"\\n\\{]*\\b'+q+r'\\b',body) or re.search(r'\\b'+q+r'\\s*\\.',body): e.add(n)
 edges.setdefault(own,set()).update(e)
controllers=[]
for p,s,own in infos:
 if 'sm-shop/src/main/' in str(p) and re.search(r'@(RestController|Controller)\\b',s): controllers.append((own,p))
for t in ['CustomerService','ProductService','PricingService','UserFacade','StoreFacade','EmailService','CountryService']:
 aff={t}; todo=[t]
 while todo:
  x=todo.pop()
  for a,bs in edges.items():
   if a not in aff and x in bs: aff.add(a);todo.append(a)
 print('\\n##',t)
 for own,p in sorted(controllers):
  if own in aff: print(own, '::', ', '.join(sorted(edges.get(own,set()) & aff)))
